(()=>{const images=['00-off.png','01-core-warming.png','02-inner-rings.png','03-operational.png'];const labels=['ANLAGE BEREIT','KERN WIRD VORBEREITET','REAKTOR 01 FÄHRT HOCH','REAKTOR 01 BETRIEBSBEREIT'];const alts=['Fünf dunkle Reaktoren um einen zentralen Kern','Der erste Reaktorkern beginnt orange zu leuchten','Der erste Reaktor erhält leuchtende Ringe','Der erste Reaktor ist orange beleuchtet und betriebsbereit'];let step=0,timer=null;const $=id=>document.getElementById(id);function render(){ $('reactor-image').src='assets/reactor-qa/'+images[step];$('reactor-image').alt=alts[step];$('stage-name').textContent=labels[step];$('stage-number').textContent=String(step+1).padStart(2,'0')+' / 04';$('stage-progress').style.width=(step/3*100)+'%';$('step-back').disabled=step===0;$('step-next').disabled=step===3;$('step-next').textContent=step===3?'Sequenz abgeschlossen':'Startsequenz fortsetzen →'}function stop(){if(timer)clearInterval(timer);timer=null;$('step-auto').textContent='Ablauf abspielen'}$('step-back').onclick=()=>{stop();step=Math.max(0,step-1);render()};$('step-next').onclick=()=>{stop();step=Math.min(3,step+1);render()};$('step-auto').onclick=()=>{if(timer){stop();return}step=0;render();$('step-auto').textContent='Ablauf anhalten';timer=setInterval(()=>{if(step>=3){stop();return}step++;render()},950)};render()})();
